const input = $json;

const clean = (value) => {
  if (value === undefined || value === null) {
    return null;
  }

  const result = String(value).trim();

  return result === ''
    ? null
    : result;
};

const title = clean(input.title);

if (!title) {
  throw new Error('title es obligatorio');
}

const allowedPriorities = [
  'low',
  'normal',
  'high',
  'urgent'
];

const priority =
  clean(input.priority) ?? 'normal';

if (!allowedPriorities.includes(priority)) {
  throw new Error(
    `priority inválida: ${priority}`
  );
}

const allowedSources = [
  'manual',
  'ai',
  'system'
];

const source =
  clean(input.source) ?? 'ai';

if (!allowedSources.includes(source)) {
  throw new Error(
    `source inválido: ${source}`
  );
}

let dueAt = clean(input.due_at);

if (dueAt) {
  const parsed = new Date(dueAt);

  if (Number.isNaN(parsed.getTime())) {
    throw new Error(
      `due_at no es una fecha válida: ${dueAt}`
    );
  }

  dueAt = parsed.toISOString();
}

return [
  {
    json: {
      task: {
        contact_id: clean(input.contact_id),
        title,
        description: clean(input.description),

        status: 'pending',
        priority,
        due_at: dueAt,
        completed_at: null,

        source
      }
    }
  }
];

const task = $json.data;

if (!task?.id) {
  throw new Error(
    'Directus no devolvió task.id'
  );
}

return [{
  json: {
    status: 'created',
    task
  }
}];
